"""Record and verify the files a private interpreter installation supplies.

Keep the inventory outside the build record: that record is also exported in
PERL_CONFIG/PYTHON_CONFIG, where a complete stdlib inventory exceeds exec's
environment limit. Additional user modules and newly generated bytecode are
allowed; the original installation's contents, links and modes must survive.
"""
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import stat

MANIFEST = 'bash-os-installation.json'
VERSION = 1


def digest(path):
    with path.open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def entry(path):
    info = path.lstat()
    mode = stat.S_IMODE(info.st_mode)
    if stat.S_ISLNK(info.st_mode):
        return dict(link=os.readlink(path))
    if stat.S_ISREG(info.st_mode):
        return dict(sha256=digest(path), mode=mode)
    if stat.S_ISDIR(info.st_mode):
        return dict(directory=True, mode=mode)
    raise ValueError(f'unsupported installation file: {path}')


def write_manifest(prefix, marker_name):
    """Write the complete staged inventory before publishing the build record."""
    entries = {}
    for directory, directories, files in os.walk(prefix, followlinks=False):
        for name in sorted(directories + files):
            path = Path(directory)/name
            relative = path.relative_to(prefix).as_posix()
            if relative not in (MANIFEST, marker_name):
                entries[relative] = entry(path)
    manifest = prefix/MANIFEST
    manifest.write_text(json.dumps(dict(version=VERSION, entries=entries),
                                   sort_keys=True, indent=2)+'\n')
    return dict(version=VERSION, manifest=MANIFEST, sha256=digest(manifest), entries=len(entries))


def read_installation(prefix, marker_name):
    """Return a verified build record, or None for old/incomplete/damaged caches."""
    try:
        marker = prefix/marker_name
        if marker.is_symlink() or not marker.is_file():
            return None
        record = json.loads(marker.read_text())
        descriptor = record['installation']
        if (descriptor['version'] != VERSION or descriptor['manifest'] != MANIFEST
                or not isinstance(record['identity']['target'], str)):
            return None
        manifest = prefix/MANIFEST
        if manifest.is_symlink() or not manifest.is_file() or digest(manifest) != descriptor['sha256']:
            return None
        inventory = json.loads(manifest.read_text())
        entries = inventory['entries']
        if (inventory['version'] != VERSION or not isinstance(entries, dict)
                or not entries or len(entries) != descriptor['entries']):
            return None
        # A parent must be a recorded real directory. Check it before its
        # children, so a replaced directory cannot redirect reads elsewhere.
        for name, expected in sorted(entries.items()):
            relative = PurePosixPath(name)
            if (relative.is_absolute() or relative.as_posix() != name or '..' in relative.parts
                    or name in ('.', MANIFEST, marker_name)):
                return None
            if relative.parent != PurePosixPath('.'):
                parent = entries.get(relative.parent.as_posix(), {})
                if parent.get('directory') is not True:
                    return None
            if entry(prefix/name) != expected:
                return None
        # Preserve the compact archive/header checksums consumed by existing
        # build manifests, and require them to agree with the full inventory.
        checksums = record['checksums']
        if not isinstance(checksums, dict) or not checksums:
            return None
        if any(entries.get(name, {}).get('sha256') != checksum
               for name, checksum in checksums.items()):
            return None
        return record
    except (OSError, ValueError, KeyError, TypeError, AttributeError):
        return None
